require_once __DIR__.'/config/app.php';require_customer();$filter=$_GET['filter']??'all';$where='o.user_id=?';$params=[current_user()['id']];if($filter==='unpaid'){$where.=" AND o.payment_status IN ('unpaid','rejected')";}elseif(in_array($filter,['processing','shipped','completed','cancelled'],true)){$where.=' AND o.order_status=?';$params[]=$filter;}$page=max(1,(int)($_GET['page']??1));$per=8;$count=db()->prepare("SELECT COUNT(*) FROM orders o WHERE $where");$count->execute($params);$total=(int)$count->fetchColumn();$pages=max(1,(int)ceil($total/$per));$offset=($page-1)*$per;$stmt=db()->prepare("SELECT o.*,(SELECT oi.product_name FROM order_items oi WHERE oi.order_id=o.id LIMIT 1) first_product,(SELECT p.image FROM order_items oi LEFT JOIN products p ON p.id=oi.product_id WHERE oi.order_id=o.id LIMIT 1) first_image,(SELECT SUM(oi.quantity) FROM order_items oi WHERE oi.order_id=o.id) item_count FROM orders o WHERE $where ORDER BY o.created_at DESC LIMIT $per OFFSET $offset");$stmt->execute($params);$orders=$stmt->fetchAll();$pageTitle='Pesanan Saya';require APP_ROOT.'/includes/header.php';
?>
<section class="page-hero"><div class="container"><div class="section-kicker">Akun pembeli</div><h1>Pesanan Saya</h1><p class="text-muted">Pantau pembayaran, pengiriman, dan nota pembelian Anda.</p></div></section><section class="pb-5"><div class="container"><div class="d-flex flex-wrap gap-2 mb-4"><?php $filters=['all'=>'Semua','unpaid'=>'Belum Dibayar','processing'=>'Diproses','shipped'=>'Dikirim','completed'=>'Selesai','cancelled'=>'Dibatalkan'];foreach($filters as $key=>$label):?><a class="btn <?= $filter===$key?'btn-primary':'btn-light' ?>" href="?filter=<?= $key ?>"><?= $label ?></a><?php endforeach;?></div><?php if(!$orders):?><div class="content-card empty-state"><i class="bi bi-receipt"></i><h4 class="fw-bold mt-3">Belum ada pesanan</h4><a class="btn btn-primary mt-2" href="<?= url('shop.php') ?>">Mulai Belanja</a></div><?php else:?><div class="vstack gap-3"><?php foreach($orders as $order):?><div class="content-card"><div class="d-flex flex-wrap align-items-center gap-2 pb-3 mb-3 border-bottom"><strong><?= e($order['order_number']) ?></strong><span class="text-muted small"><?= date('d M Y, H:i',strtotime($order['created_at'])) ?></span><span class="badge text-bg-<?= status_class($order['order_status']) ?> ms-md-auto"><?= order_status_label($order['order_status']) ?></span><span class="badge text-bg-<?= status_class($order['payment_status']) ?>"><?= payment_status_label($order['payment_status']) ?></span></div><div class="row align-items-center g-3"><div class="col-3 col-md-1"><img class="w-100 rounded-3" style="aspect-ratio:1;object-fit:cover" src="<?= e(product_image($order['first_image'])) ?>"></div><div class="col-9 col-md-5"><strong><?= e($order['first_product']) ?></strong><div class="small text-muted"><?= (int)$order['item_count'] ?> barang • <?= $order['fulfillment_method']==='pickup'?'COD DI TOKO':strtoupper($order['payment_method']) . ' ANTAR' ?></div></div><div class="col-6 col-md-3"><small class="text-muted d-block">Total</small><strong class="text-primary"><?= rupiah($order['total_amount']) ?></strong></div><div class="col-6 col-md-3 text-end"><a class="btn btn-light-green btn-sm" href="<?= url('order-detail.php?id='.$order['id']) ?>">Detail</a><a class="btn btn-primary btn-sm" href="<?= url('invoice.php?id='.$order['id']) ?>">Nota</a></div></div></div><?php endforeach;?></div><?php if($pages>1):?><nav class="mt-4"><ul class="pagination justify-content-center"><?php for($i=1;$i<=$pages;$i++):?><li class="page-item <?= $i===$page?'active':'' ?>"><a class="page-link" href="?<?= e(query_string(['page'=>$i])) ?>"><?= $i ?></a></li><?php endfor;?></ul></nav><?php endif;?><?php endif;?></div></section>
